const escapeXml = (t) =>
  String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const round = (n) => Math.round(n * 10) / 10;

/**
 * SVG markup for one circuit.
 *   .circuit-ghost  faint full outline
 *   .circuit-line   the lap; pathLength="1" so the page can animate
 *                   stroke-dasharray: 1 with stroke-dashoffset 1 -> 0
 *   .circuit-start  tick across the track at the start/finish line
 *   .circuit-labels <text> per corner (only when labels is true)
 */
export function circuitSVG(id, { stroke = 'currentColor', width = 4, labels = false } = {}) {
  const c = CIRCUITS[id];
  if (!c) return '';
  const a = ((c.start.angle + 90) * Math.PI) / 180;
  const half = Math.max(10, width * 3);
  const dx = Math.cos(a) * half;
  const dy = Math.sin(a) * half;
  const s = escapeXml(stroke);
  const common = `fill="none" stroke="${s}" stroke-linecap="round" stroke-linejoin="round"`;
  let out =
    `<svg class="circuit circuit--${c.id}" xmlns="http://www.w3.org/2000/svg" viewBox="${c.viewBox}" fill="none" role="img" aria-label="${escapeXml(c.name)} circuit outline">` +
    `<path class="circuit-ghost" d="${c.d}" ${common} stroke-width="${width}" stroke-opacity="0.18"/>` +
    `<path class="circuit-line" d="${c.d}" pathLength="1" ${common} stroke-width="${width}"/>` +
    `<line class="circuit-start" x1="${round(c.start.x - dx)}" y1="${round(c.start.y - dy)}" x2="${round(c.start.x + dx)}" y2="${round(c.start.y + dy)}" stroke="${s}" stroke-width="${width}" stroke-linecap="round"/>`;
  if (labels) {
    out +=
      `<g class="circuit-labels" fill="${s}" stroke="none" font-size="15">` +
      c.corners
        .map((k) => `<text x="${k.x}" y="${k.y}" text-anchor="${k.anchor || 'middle'}">${escapeXml(k.name)}</text>`)
        .join('') +
      `</g>`;
  }
  return out + `</svg>`;
}
